<?php
declare(strict_types=1);
if (!defined('ABSPATH')) exit;
$cart = $GLOBALS['es_wc_cart'] ?? null;
if (!$cart && function_exists('WC')) { try { $woo = WC(); $cart = is_object($woo) ? ($woo->cart ?? null) : null; } catch (Throwable) { $cart = null; } }
$items = is_object($cart) && method_exists($cart, 'get_cart') ? (array) $cart->get_cart() : [];
$cartUrl = function_exists('wc_get_cart_url') ? wc_get_cart_url() : home_url('/cart/');
$checkoutUrl = function_exists('wc_get_checkout_url') ? wc_get_checkout_url() : home_url('/checkout/');
$money = static function (mixed $amount): string { return function_exists('wc_price') ? (string) wc_price((float) $amount) : esc_html(number_format_i18n((float) $amount) . ' تومان'); };
$count = is_object($cart) && method_exists($cart, 'get_cart_contents_count') ? (int) $cart->get_cart_contents_count() : 0;
$subtotal = is_object($cart) && method_exists($cart, 'get_subtotal') ? (float) $cart->get_subtotal() : 0;
$tax = is_object($cart) && method_exists($cart, 'get_cart_tax') ? (float) $cart->get_cart_tax() : 0;
$total = is_object($cart) && method_exists($cart, 'get_total') ? (float) $cart->get_total('edit') : $subtotal + $tax;
?>
<section class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8" data-cart-page="true">
    <header class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-bold text-emerald-700">سفارش آنلاین</p><h1 class="mt-1 text-2xl font-black text-slate-900">سبد خرید</h1></div><span class="rounded-full bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800"><span data-cart-count="true"><?php echo esc_html((string) $count); ?></span> کالا</span></header>
    <?php if ($items !== []) : ?><form class="woocommerce-cart-form" action="<?php echo esc_url($cartUrl); ?>" method="post">
        <div class="grid gap-6 lg:grid-cols-[minmax(0,1fr)_340px]"><div data-cart-items-list="true" class="space-y-3">
            <?php foreach ($items as $key => $item) : if (!is_array($item)) continue; $product = $item['data'] ?? null; if (!is_object($product)) continue; $productId = (int) ($item['product_id'] ?? (method_exists($product, 'get_id') ? $product->get_id() : 0)); $quantity = max(1, (int) ($item['quantity'] ?? 1)); $price = method_exists($product, 'get_price') ? (float) $product->get_price() : 0; $line = (float) ($item['line_total'] ?? $price * $quantity) + (float) ($item['line_tax'] ?? 0); $name = method_exists($product, 'get_name') ? $product->get_name() : get_the_title($productId); $permalink = method_exists($product, 'get_permalink') ? $product->get_permalink() : get_permalink($productId); $image = method_exists($product, 'get_image') ? $product->get_image('thumbnail') : get_the_post_thumbnail($productId, 'thumbnail'); $removeUrl = function_exists('wc_get_cart_remove_url') ? wc_get_cart_remove_url((string) $key) : add_query_arg(['remove_item' => rawurlencode((string) $key)], $cartUrl); ?>
                <article class="grid gap-4 rounded-2xl border border-slate-200 bg-white p-4 sm:grid-cols-[96px_minmax(0,1fr)_auto] sm:items-center" data-cart-item-row="<?php echo esc_attr((string) $key); ?>">
                    <a href="<?php echo esc_url($permalink); ?>" class="block overflow-hidden rounded-xl"><?php echo wp_kses_post($image); ?></a>
                    <div><h2 class="font-bold text-slate-900"><a href="<?php echo esc_url($permalink); ?>"><?php echo esc_html($name); ?></a></h2><p class="mt-1 text-xs text-slate-500"><?php echo wp_kses_post($money($price)); ?> / عدد</p><a href="<?php echo esc_url($removeUrl); ?>" data-cart-remove="<?php echo esc_attr((string) $key); ?>" class="mt-2 inline-block text-xs font-bold text-rose-700">حذف</a></div>
                    <div class="flex items-center gap-3 sm:flex-col sm:items-end"><div class="flex items-center gap-2"><button type="button" data-cart-qty-dec="<?php echo esc_attr((string) $key); ?>" aria-label="کاهش تعداد" class="grid h-8 w-8 place-items-center rounded-lg border">−</button><input type="number" min="1" step="1" name="cart[<?php echo esc_attr((string) $key); ?>][qty]" value="<?php echo esc_attr((string) $quantity); ?>" data-cart-qty-val="<?php echo esc_attr((string) $key); ?>" class="w-16 rounded-lg border px-2 py-1 text-center" aria-label="تعداد"><button type="button" data-cart-qty-inc="<?php echo esc_attr((string) $key); ?>" aria-label="افزایش تعداد" class="grid h-8 w-8 place-items-center rounded-lg border">+</button></div><strong data-cart-row-total="<?php echo esc_attr((string) $key); ?>" class="text-sm font-black"><?php echo wp_kses_post($money($line)); ?></strong></div>
                </article>
            <?php endforeach; ?>
        </div><aside class="h-fit rounded-2xl border border-slate-200 bg-white p-5"><h2 class="mb-4 font-black">خلاصه سفارش</h2><dl class="space-y-3 text-sm"><div class="flex justify-between"><dt>جمع جزء</dt><dd data-cart-subtotal="true"><?php echo wp_kses_post($money($subtotal)); ?></dd></div><div class="flex justify-between"><dt>مالیات</dt><dd data-cart-tax="true"><?php echo wp_kses_post($money($tax)); ?></dd></div><div class="flex justify-between border-t pt-3 font-black"><dt>مبلغ قابل پرداخت</dt><dd data-cart-grandtotal="true"><?php echo wp_kses_post($money($total)); ?></dd></div></dl><button type="submit" name="update_cart" value="1" class="mt-4 w-full rounded-xl border px-4 py-3 text-sm font-bold">به‌روزرسانی سبد</button><?php wp_nonce_field('woocommerce-cart', 'woocommerce-cart-nonce'); ?><a href="<?php echo esc_url($checkoutUrl); ?>" class="mt-3 block rounded-xl bg-emerald-700 px-4 py-3 text-center text-sm font-extrabold text-white">ادامه و تسویه‌حساب</a></aside></div>
    </form><?php else : ?><div data-cart-empty="true" class="rounded-3xl bg-white p-10 text-center"><p class="text-lg font-black">سبد خرید شما خالی است.</p><a href="<?php echo esc_url(function_exists('wc_get_page_permalink') ? wc_get_page_permalink('shop') : home_url('/shop/')); ?>" class="mt-4 inline-block rounded-xl bg-emerald-700 px-5 py-3 text-sm font-bold text-white">رفتن به فروشگاه</a></div><div data-cart-items-list="true" class="hidden"></div><?php endif; ?>
</section>
